// pnpm engine:furniture [--check] (tsx: imports the TypeScript sources) — the furniture for the native
// client, GENERATED by the web's own code: every catalog kind (closed, and open where it opens) is built
// by apps/client/src/craft/furniture/model.ts buildFurnitureShape — the same three.js geometry the web
// draws — and written to engine/assets/furniture/ as
//   furniture.json  per kind: placement, size, surface height, per shape the ranges in the bin and the
//                   vertex count of each part, and each variant's part colours (sRGB hex, resolved)
//   furniture.bin   float32 positions, float32 normals, uint32 indices (little-endian, in that order)
// so the app never re-implements a rounded box. --check (CI) fails when either file is stale.
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { buildFurnitureShape } from "../apps/client/src/craft/furniture/model.ts";
import { CATALOG, variantCount } from "../packages/shared/src/furniture/catalog/index.ts";

const dir = fileURLToPath(new URL("../engine/assets/furniture/", import.meta.url));
const positions = [];
const normals = [];
const indices = [];
let vertexBase = 0;

function resolve(def, variant, ref) {
  if (typeof ref === "number") return ref;
  const palette = def.palettes?.[variant] ?? def.palettes?.[0];
  return palette?.colors[ref] ?? 0xff00ff;
}

function shape(def, open) {
  const { geometry, partVertices } = buildFurnitureShape(def, open);
  const p = geometry.getAttribute("position");
  const n = geometry.getAttribute("normal");
  const idx = geometry.index;
  if (!idx) throw new Error(`${def.key}: furniture geometry must be indexed`);
  const vstart = vertexBase;
  for (let i = 0; i < p.count; i++) {
    positions.push(p.getX(i), p.getY(i), p.getZ(i));
    normals.push(n.getX(i), n.getY(i), n.getZ(i));
  }
  const istart = indices.length;
  for (let i = 0; i < idx.count; i++) indices.push(idx.getX(i));
  vertexBase += p.count;
  geometry.dispose();
  const parts = open && def.openParts ? def.openParts : def.parts;
  const colors = [];
  for (let v = 0; v < variantCount(def); v++) colors.push(parts.map((part) => resolve(def, v, part.color)));
  return { vertex: vstart, vertices: p.count, index: istart, indices: idx.count, parts: partVertices, colors };
}

const kinds = CATALOG.map((def) => ({
  key: def.key,
  placement: def.placement,
  size: [def.size.w, def.size.d, def.size.h],
  surface: def.surface ?? 0,
  closed: shape(def, false),
  ...(def.openParts ? { open: shape(def, true) } : {}),
}));

const json = JSON.stringify({ version: 1, rugTop: 0.14, kinds }, null, 1) + "\n";
const bin = Buffer.alloc((positions.length + normals.length + indices.length) * 4);
let o = 0;
for (const v of positions) { bin.writeFloatLE(v, o); o += 4; }
for (const v of normals) { bin.writeFloatLE(v, o); o += 4; }
for (const v of indices) { bin.writeUInt32LE(v, o); o += 4; }

if (process.argv.includes("--check")) {
  const read = (f) => { try { return readFileSync(dir + f); } catch { return Buffer.alloc(0); } };
  const staleJson = read("furniture.json").toString("utf8").replace(/\r\n/g, "\n") !== json;
  if (staleJson || !read("furniture.bin").equals(bin)) {
    console.error("engine/assets/furniture is stale: run pnpm engine:furniture");
    process.exit(1);
  }
  console.log("furniture export up to date");
} else {
  mkdirSync(dir, { recursive: true });
  writeFileSync(dir + "furniture.json", json);
  writeFileSync(dir + "furniture.bin", bin);
  console.log(`wrote ${kinds.length} kinds, ${vertexBase} vertices, ${indices.length / 3} triangles, ${(bin.length / 1024 / 1024).toFixed(2)} MB`);
}
